import java.util.Scanner;

public class Main {
    static long[] nrs = new long[16];

    static long recursiveProcess(long k, int i, int bitmask) {
        if (k == 0) return 0;
        long l = k;
        l = ((l % nrs[i]) + nrs[i]) % nrs[i];
        if ((bitmask & 1) != 0) l -= nrs[i];
        long costValue = (Math.abs(k - l) / nrs[i]) * (i + 1);
        return costValue + recursiveProcess(l, i - 1, bitmask >> 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        nrs[0] = 1;
        for (int i = 1; i < 16; ++i)
            nrs[i] = nrs[i - 1] * 10 + 1;
        long minAns = n;
        for (int mask = 0; mask < (1 << 15); ++mask) {
            minAns = Math.min(minAns, recursiveProcess(n, 15, mask));
        }
        System.out.println(minAns);
        sc.close();
    }
}
